	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"detail_id" uuid NOT NULL,
	"kind" "custody_event_kind" NOT NULL,
	"quantity" double precision NOT NULL,
	"event_date" timestamp NOT NULL,
	"from_employee_number" integer,
	"to_employee_number" integer,
	"reason" text DEFAULT '' NOT NULL,
	"warehouse_movement_id" integer,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" text,
	CONSTRAINT "custody_events_quantity_check" CHECK ("custody_events"."quantity" > 0),
	CONSTRAINT "custody_events_transfer_target_check" CHECK ("custody_events"."kind" <> 'transfer' OR ("custody_events"."from_employee_number" IS NOT NULL AND "custody_events"."to_employee_number" IS NOT NULL AND "custody_events"."from_employee_number" <> "custody_events"."to_employee_number")),
	CONSTRAINT "custody_events_non_transfer_target_check" CHECK ("custody_events"."kind" = 'transfer' OR "custody_events"."to_employee_number" IS NULL)
);
